var e=[[1,1],[16,15],[9,8],[6,5],[5,4],[4,3],[45,32],[3,2],[8,5],[5,3],[9,5],[15,8],[2,1]],t=[`lateralClosed`,`counterCurrent`,`lateralOpen`,`concurrent`];function n(t){let n=e.length-1,r=t*n,i=Math.floor(r),a=r-i,o=e=>e*e*(3-2*e);return(i+o(o(a)))/n}function r(e,t,n,r,i){let a=t[0],o=t[1];if(!isFinite(a)||!isFinite(o)||!isFinite(e))return{x:0,y:0};switch(n){case`lateralOpen`:return{x:r*Math.sin(a*e),y:r*Math.sin(o*e)};case`lateralClosed`:return{x:r*Math.cos(a*e),y:r*Math.sin(o*e)};case`concurrent`:{let t=i*(1+.6*Math.sin(o*e)),n=a*e;return{x:t*Math.cos(n),y:t*Math.sin(n)}}case`counterCurrent`:{let t=i*(1+.6*Math.sin(o*e)),n=(a-o)*e;return{x:t*Math.cos(n),y:t*Math.sin(n)}}default:return{x:0,y:0}}}var i={id:`harmonics`,title:`Musical Harmonics`,category:`parametric`,description:`Visualisation of 13 just-intonation musical intervals as Lissajous and polar parametric curves, cycling continuously through interval ratios and 4 view modes over a configurable period.`,version:`2.0.0`,canvas:{width:800,height:800,context:`2d`},animation:{type:`loop`,loopDuration:720,loopFrames:43200,defaultFps:60,defaultSpeed:1,canPrerender:!0,animatableParams:[],sequencer:!0,animationExport:!0},export:{png:!0,svg:!1,gif:!0,webm:!0,sequence:!0},infoSections:[{heading:`DESCRIPTION`,body:`Harmonics visualises the 13 just-intonation musical intervals (unison through octave) as parametric curves — specifically as Lissajous and polar variants — cycling continuously through interval ratios and view modes over a configurable period. The generator draws a scatter plot of particles tracing the current interval curve. Each frame, a translucent black overlay creates a motion-blur accumulation effect; the motionBlur parameter controls the alpha of this overlay and thereby the decay rate of trails. The 13 intervals in ascending order are: unison (1:1), minor second (16:15), major second (9:8), minor third (6:5), major third (5:4), perfect fourth (4:3), tritone (45:32), perfect fifth (3:2), minor sixth (8:5), major sixth (5:3), minor seventh (9:5), major seventh (15:8), and octave (2:1). The full animation cycle is passDuration times 8 seconds (default 720 seconds, 12 minutes). The cycle is divided into 8 passes. Alternating passes ascend (unison to octave) and descend (octave to unison) through the interval ratios. Each consecutive pair of passes covers one of the four view modes. View cross-fading occurs during descending passes only, linearly interpolating particle positions between the current and next view geometry.`},{heading:`ALGORITHM`,body:`Four parametric coordinate functions are implemented in getCoordinates: lateralClosed (Lissajous cos/sin) x = scale * cos(a * t), y = scale * sin(b * t); lateralOpen (Lissajous sin/sin) x = scale * sin(a * t), y = scale * sin(b * t); concurrent (polar, same direction) r = baseRadius * (1 + 0.6 * sin(b * t)), theta = a * t; counterCurrent (polar, differential) r = baseRadius * (1 + 0.6 * sin(b * t)), theta = (a - b) * t. Scale constants: scale = min(W, H) * 0.35, baseRadius = scale * 0.7. timeWarp implements double-smoothstep per interval segment: scaledProgress = x * 12, currentInterval = floor(scaledProgress), localProgress = scaledProgress - currentInterval, eased = smoothstep(smoothstep(localProgress)), returns (currentInterval + eased) / 12, where smoothstep(t) = t^2 * (3 - 2t). Animation state is derived entirely from the frame counter in draw: elapsed = frame / fps, cycleTime = elapsed mod totalCycleDuration, passIndex = floor(cycleTime / passDuration), timeInPass = cycleTime mod passDuration, isAscending = passIndex mod 2 == 0. Interval interpolation: ratioProgress = warpedProgress * 12 for ascending or 12 * (1 - warpedProgress) for descending; ratioIndex = floor(ratioProgress); a and b are linearly interpolated between adjacent interval ratio pairs at fractional ratioT. View interpolation during descending passes: x_final = cx + current.x * (1 - viewProgress) + next.x * viewProgress (viewProgress = warpedProgress on descending, 0 on ascending). Cycles per pass: cycles = max(2, ceil(max(a, b)) * 2), ensuring all curve petals complete within [0, 2pi * cycles]. Render pipeline per frame: (1) compute elapsed, cycleTime, passIndex from frame counter; (2) determine isAscending, current and next view indices; (3) apply timeWarp; (4) compute interpolated frequency ratio [a, b]; (5) partial canvas clear via globalAlpha + fillRect; (6) batch all particle arcs into a single path, or use fillRect for pointSize <= 1; (7) single fill call.`},{heading:`PARAMETERS`,body:`Display group. motionBlur [slider, 0.01 to 0.2, step 0.01, default 0.05]: alpha of the black overlay applied each frame; lower values leave longer trails (slower decay), higher values clear the canvas more quickly. points [slider, 100 to 3000, step 100, default 800]: number of particles distributed evenly over the parameter curve; higher values produce a denser, more continuous curve appearance. pointSize [slider, 0.5 to 4, step 0.5, default 1]: radius of each particle in canvas pixels; values of 1 or below use fillRect for performance. Timing group. passDuration [slider, 30 to 180, step 10, default 90]: duration in seconds of each individual pass through the 13-interval sequence; total cycle duration is passDuration * 8 seconds (default 720 s). Changing passDuration scales the entire animation duration proportionally and updates loopFrames. Parameter interactions: motionBlur and points interact visually — high points with low motionBlur produces a dense persistent curve; low points with high motionBlur produces an animated scatter with rapid decay.`},{heading:`PRESETS`,body:`Default: 800 points, pointSize 1, motionBlur 0.05, passDuration 90 s. Full 720-second cycle. Balanced entry point showing all 13 intervals and 4 views at moderate density. Fast Cycle: 600 points, motionBlur 0.08, passDuration 30 s. Completes a full cycle in 240 seconds with more visible blur decay; suitable for quick previewing. Dense: 2000 points, pointSize 0.5, motionBlur 0.03, passDuration 90 s. High particle density with slow trail decay, producing near-continuous curve appearance over a 720-second cycle. Minimal: 400 points, pointSize 2, motionBlur 0.02, passDuration 120 s. Sparse large points with very slow trail decay over a 960-second cycle; emphasises individual point motion.`},{heading:`PERFORMANCE`,body:`Complexity class: O(points) per frame — points arc or fillRect draw calls plus 2 * points getCoordinates invocations (approximately 4 trigonometric operations each). At default (800 points): approximately 1600 trig calls plus 800 draw operations, estimated 2 to 5 ms per frame. At maximum (3000 points, pointSize 4): approximately 6000 trig calls plus 3000 arc calls, estimated 8 to 15 ms per frame, borderline at 60 fps. Mitigation 1: all particle arcs are batched into a single canvas path per frame (beginPath once, all ctx.arc calls, fill once), yielding an estimated 3 to 5 times speedup over individual path flushes. Mitigation 2: for pointSize at or below 1, ctx.fillRect is used instead of ctx.arc, which is faster for sub-pixel points. Time warp and interval interpolation are O(1) per frame. Partial canvas clear is one fillRect call per frame (constant cost). Memory: getCoordinates allocates one {x, y} object per call — 2 per point loop iteration, approximately 6000 GC objects per frame at maximum points (360000 per second at 60 fps). No other significant per-frame allocations.`},{heading:`ANIMATION`,body:`Animation type: loop. loopFrames: passDuration * 8 * fps (dynamically updated each draw call; default 43200 at passDuration 90, fps 60). defaultFps: 60. defaultSpeed: 1. canPrerender: true. The animation is fully deterministic: elapsed = frame / fps. No wall-clock time (Date.now()), no random state. Given the same frame index and parameters, draw always produces identical output. This makes GIF and WebM pre-rendering reliable. animatableParams is empty: the internal 8-pass cycle drives all visual change through the frame counter; there are no external phase or offset parameters to interpolate between saved states. Ascending passes (even passIndex) move from unison to octave via timeWarp and hold the current view; descending passes (odd passIndex) return from octave to unison while cross-fading to the next view geometry.`},{heading:`KNOWN LIMITATIONS`,body:`Ratio label not rendered: the animation displays no on-canvas label for the current interval name or frequency ratio. The legacy implementation displayed the current ratio via a host status mechanism not available in the gen.js format. Speed control and play/pause controls are not implemented; playback rate is determined by passDuration and the host frame counter only. loopFrames accuracy: loopFrames is updated dynamically from passDuration on each draw call; hosts that read loopFrames before the first draw will see the default value (43200, corresponding to passDuration 90). Export of GIF or WebM at non-default passDuration will capture the correct loop only if the host queries loopFrames after at least one draw call.`},{heading:`REFERENCES`,body:`Adapted from the harmonics variant of the Lissajous reference implementation. Version 2.0.0. Mathematical basis: just-intonation frequency ratios from standard Western music theory. Double-smoothstep time warp is an original animation device producing natural pauses at pure harmonic ratios.`}],presets:[{name:`Default`,values:{motionBlur:.05,passDuration:90,points:800,pointSize:1}},{name:`Fast Cycle`,values:{motionBlur:.08,passDuration:30,points:600,pointSize:1}},{name:`Dense`,values:{motionBlur:.03,passDuration:90,points:2e3,pointSize:.5}},{name:`Minimal`,values:{motionBlur:.02,passDuration:120,points:400,pointSize:2}}],parameters:[{group:`Display`,params:[{key:`motionBlur`,type:`slider`,label:`Motion Blur`,min:.01,max:.2,step:.01,default:.05,precision:2},{key:`points`,type:`slider`,label:`Points`,min:100,max:3e3,step:100,default:800},{key:`pointSize`,type:`slider`,label:`Point Size`,min:.5,max:4,step:.5,default:1,precision:1}]},{group:`Timing`,params:[{key:`passDuration`,type:`slider`,label:`Pass Duration`,min:30,max:180,step:10,default:90}]}],draw(a,o,s,c){let l=s.fps||60,u=s.passDuration||90,d=u*8;i.animation.loopFrames=Math.round(u*8*l);let f=c/l%d,p=Math.floor(f/u),m=f%u,h=p%2==0,g=Math.floor(p/2),_=g%t.length,v=(g+1)%t.length,y=n(m/u),b=h?y*(e.length-1):(e.length-1)*(1-y),x=h?0:y,S=Math.floor(b),C=b-S,w=Math.min(Math.max(S,0),e.length-1),T=Math.min(Math.max(S+1,0),e.length-1),E=[e[w][0]+(e[T][0]-e[w][0])*C,e[w][1]+(e[T][1]-e[w][1])*C];a.globalAlpha=s.motionBlur||.05,a.fillStyle=`#000000`,a.fillRect(0,0,o.width,o.height),a.globalAlpha=1;let D=o.width,O=o.height,k=D/2,A=O/2,j=Math.min(D,O)*.35,M=j*.7,N=s.points||800,P=s.pointSize||1,F=Math.max(2,Math.ceil(Math.max(E[0],E[1]))*2),I=t[_],L=t[v];if(a.fillStyle=`#c0c0c0`,P<=1)for(let e=0;e<N;e++){let t=e/N*Math.PI*2*F,n=r(t,E,I,j,M),i=n.x,o=n.y,s=r(t,E,L,j,M),c=k+i*(1-x)+s.x*x,l=A+o*(1-x)+s.y*x;a.fillRect(c-.5,l-.5,1,1)}else{a.beginPath();for(let e=0;e<N;e++){let t=e/N*Math.PI*2*F,n=r(t,E,I,j,M),i=n.x,o=n.y,s=r(t,E,L,j,M),c=k+i*(1-x)+s.x*x,l=A+o*(1-x)+s.y*x;a.moveTo(c+P,l),a.arc(c,l,P,0,Math.PI*2)}a.fill()}}};export{i as SCRIPT_CONFIG};